import static org.mockito.Mockito.when;

public class JSTypeRegistry_canPropertyBeDefined_TriageGen2Test {

    private JSTypeRegistry registry;
    private ErrorReporter errorReporter;

    @Before
    public void setUp() {
        errorReporter = mock(ErrorReporter.class);
        registry = new JSTypeRegistry(errorReporter);
    }

    /**
     * Tests the case where the property name is not present in the registry at all.
     * Covers: if (typesIndexedByProperty.containsKey(propertyName)) -> false
     */
    @Test
    public void testCanPropertyBeDefined_PropertyNotIndexed() {
        JSType type = mock(JSType.class);
        String propertyName = "nonExistentProperty";

        assertFalse(registry.canPropertyBeDefined(type, propertyName));
    }

    /**
     * Tests the case where the property is indexed, but the greatest subtype
     * of the provided type against the registered alternates is an EmptyType.
     * Covers: if (!greatestSubtype.isEmptyType()) -> false
     */
    @Test
    public void testCanPropertyBeDefined_GreatestSubtypeIsEmpty() {
        JSType type = mock(JSType.class);
        String propertyName = "myProp";

        // Create a mock for the type that holds the property
        JSType propertyHolderType = mock(JSType.class);
        JSType alternate = mock(JSType.class);

        // Mock the behavior of getAlternates() for the property holder
        when(propertyHolderType.getAlternates()).thenReturn(Collections.singletonList(alternate));

        // Mock the behavior of getGreatestSubtype returning an EmptyType
        JSType emptyType = mock(JSType.class);
        when(emptyType.isEmptyType()).thenReturn(true);
        when(alternate.getGreatestSubtype(type)).thenReturn(emptyType);

        // Register the property
        registry.registerPropertyOnType(propertyName, propertyHolderType);

        assertFalse(registry.canPropertyBeDefined(type, propertyName));
    }

    /**
     * Tests the success case where the property is indexed and a valid
     * non-empty subtype is found.
     * Covers: if (!greatestSubtype.isEmptyType()) -> true
     */
    @Test
    public void testCanPropertyBeDefined_Success() {
        JSType type = mock(JSType.class);
        String propertyName = "validProp";

        // Create a mock for the type that holds the property
        JSType propertyHolderType = mock(JSType.class);
        JSType alternate = mock(JSType.class);

        // Mock the behavior of getAlternates()
        when(propertyHolderType.getAlternates()).thenReturn(Collections.singletonList(alternate));

        // Mock the behavior of getGreatestSubtype returning a non-empty type
        JSType validType = mock(JSType.class);
        when(validType.isEmptyType()).thenReturn(false);
        when(alternate.getGreatestSubtype(type)).thenReturn(validType);

        // Register the property
        registry.registerPropertyOnType(propertyName, propertyHolderType);

        assertTrue(registry.canPropertyBeDefined(type, propertyName));
    }

    /**
     * Tests the loop behavior where the first alternate results in an empty type,
     * but a subsequent alternate results in a valid type.
     * Covers: loop through alternates
     */
    @Test
    public void testCanPropertyBeDefined_MultipleAlternates() {
        JSType type = mock(JSType.class);
        String propertyName = "multiProp";

        JSType propertyHolderType = mock(JSType.class);
        JSType emptyAlternate = mock(JSType.class);
        JSType validAlternate = mock(JSType.class);

        // Setup alternates: first is empty, second is valid
        when(propertyHolderType.getAlternates()).thenReturn(java.util.Arrays.asList(emptyAlternate, validAlternate));

        // First alternate returns empty
        JSType emptyType = mock(JSType.class);
        when(emptyType.isEmptyType()).thenReturn(true);
        when(emptyAlternate.getGreatestSubtype(type)).thenReturn(emptyType);

        // Second alternate returns valid
        JSType validType = mock(JSType.class);
        when(validType.isEmptyType()).thenReturn(false);
        when(validAlternate.getGreatestSubtype(type)).thenReturn(validType);

        registry.registerPropertyOnType(propertyName, propertyHolderType);

        assertTrue(registry.canPropertyBeDefined(type, propertyName));
    }
}
